import React, { useEffect, useMemo, useState } from 'react';
import { getOrgChart, updateOrgChart } from '../services/adminService';
import { toast } from 'react-toastify';
import { FiUsers, FiUser, FiMail, FiBriefcase, FiShield, FiTarget, FiActivity, FiTrendingUp, FiRefreshCw, FiFilter, FiSearch, FiSettings, FiChevronDown, FiChevronRight, FiMapPin, FiCalendar, FiAward, FiZap, FiGitBranch, FiGitMerge } from 'react-icons/fi';

const OrgChart = () => {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedDepartments, setExpandedDepartments] = useState({});
  const [expandedUsers, setExpandedUsers] = useState({});

  const normalizeText = (value) =>
    (value || '').toString().toLowerCase().trim();

  const getRoleIcon = (role) => {
    switch (role) {
      case 'admin': return <FiShield className="w-4 h-4" />;
      case 'validator': return <FiAward className="w-4 h-4" />;
      case 'manager': return <FiTarget className="w-4 h-4" />;
      default: return <FiUser className="w-4 h-4" />;
    }
  };

  const getRoleColor = (role) => {
    switch (role) {
      case 'admin': return 'bg-red-50 text-red-700 border-red-200';
      case 'validator': return 'bg-blue-50 text-blue-700 border-blue-200';
      case 'manager': return 'bg-green-50 text-green-700 border-green-200';
      default: return 'bg-gray-50 text-gray-700 border-gray-200';
    }
  };

  const getAvatarColor = (name) => {
    const colors = ['#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899', '#06b6d4', '#84cc16'];
    const index = name.charCodeAt(0) % colors.length;
    return colors[index];
  };

  const toggleDepartment = (deptKey) => {
    setExpandedDepartments(prev => ({
      ...prev,
      [deptKey]: !prev[deptKey]
    }));
  };

  const toggleUser = (userId) => {
    setExpandedUsers(prev => ({
      ...prev,
      [userId]: !prev[userId]
    }));
  };

  const managerNameByUser = useMemo(() => {
    return users.reduce((acc, user) => {
      acc[user.id] = user.fullName;
      return acc;
    }, {});
  }, [users]);

  const filteredUsers = useMemo(() => {
    if (!searchTerm) return users;
    return users.filter(user => 
      user.fullName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.department.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.role.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [users, searchTerm]);

  const filteredDepartmentHierarchy = useMemo(() => {
    const nodes = {};
    filteredUsers.forEach((user) => {
      nodes[user.id] = { ...user, children: [] };
    });

    const roots = {};
    filteredUsers.forEach((user) => {
      const departmentKey = user.departmentKey || normalizeText(user.department) || 'sans_departement';
      if (!roots[departmentKey]) roots[departmentKey] = { label: user.department || 'Sans département', users: [] };
      const managerNode = user.effectiveManagerId ? nodes[user.effectiveManagerId] : null;

      if (managerNode && ((managerNode.departmentKey || normalizeText(managerNode.department)) === departmentKey)) {
        managerNode.children.push(nodes[user.id]);
      } else {
        roots[departmentKey].users.push(nodes[user.id]);
      }
    });

    Object.values(roots).forEach((group) => {
      group.users.sort((a, b) => Number(a.hierarchyLevel) - Number(b.hierarchyLevel));
    });

    return roots;
  }, [filteredUsers]);

  const loadOrgChart = async () => {
    try {
      const data = await getOrgChart();
      const sorted = [...data].sort((a, b) => {
        if (a.department !== b.department) {
          return String(a.department).localeCompare(String(b.department));
        }
        if (Number(a.hierarchyLevel) !== Number(b.hierarchyLevel)) {
          return Number(a.hierarchyLevel) - Number(b.hierarchyLevel);
        }
        return String(a.fullName).localeCompare(String(b.fullName));
      });
      setUsers(sorted);
    } catch (error) {
      toast.error('Erreur lors du chargement de l organigramme');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadOrgChart();
  }, []);

  const renderUserNode = (user, level = 0) => {
    const isExpanded = expandedUsers[user.id];
    const hasChildren = user.children.length > 0;

    return (
      <div key={user.id} className="animate-fadeIn" style={{ animationDelay: `${level * 50}ms` }}>
        <div className="bg-white rounded-2xl border border-gray-100 shadow-sm hover:shadow-lg transition-all duration-300 p-6 mb-4">
          <div className="flex items-start justify-between mb-4">
            <div className="flex items-center gap-4">
              <div className="relative">
                <div
                  className="w-12 h-12 rounded-full flex items-center justify-center text-white font-bold shadow-lg"
                  style={{ backgroundColor: getAvatarColor(user.fullName) }}
                >
                  {user.fullName.charAt(0).toUpperCase()}
                </div>
                <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 rounded-full border-2 border-white"></div>
              </div>
              <div>
                <h3 className="text-lg font-semibold text-gray-900">{user.fullName}</h3>
                <div className="flex items-center gap-2 mt-1">
                  {getRoleIcon(user.role)}
                  <span className="text-sm text-gray-600 capitalize">{user.role || 'Rôle non défini'}</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <span className="px-3 py-1 bg-gradient-to-r from-blue-500 to-indigo-600 text-white text-xs font-semibold rounded-full">
                Niveau {user.hierarchyLevel}
              </span>
              {hasChildren && (
                <button
                  onClick={() => toggleUser(user.id)}
                  className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                >
                  {isExpanded ? <FiChevronDown className="w-4 h-4" /> : <FiChevronRight className="w-4 h-4" />}
                </button>
              )}
            </div>
          </div>

          <div className="grid gap-3">
            <div className="flex items-center gap-2 p-3 bg-gray-50 rounded-lg">
              <FiBriefcase className="w-4 h-4 text-gray-500" />
              <div>
                <p className="text-xs text-gray-500">Département</p>
                <p className="text-sm font-medium text-gray-900">{user.department || 'Non spécifié'}</p>
              </div>
            </div>

            <div className="flex items-center gap-2 p-3 bg-gray-50 rounded-lg">
              <FiMail className="w-4 h-4 text-gray-500" />
              <div>
                <p className="text-xs text-gray-500">Email</p>
                <p className="text-sm font-medium text-gray-900">{user.email || 'Non spécifié'}</p>
              </div>
            </div>

            <div className="flex items-center gap-2 p-3 bg-gray-50 rounded-lg">
              <FiUsers className="w-4 h-4 text-gray-500" />
              <div>
                <p className="text-xs text-gray-500">Manager</p>
                <p className="text-sm font-medium text-gray-900">
                  {user.effectiveManagerId ? user.effectiveManagerName || managerNameByUser[user.effectiveManagerId] : 'Aucun'}
                </p>
              </div>
            </div>
          </div>
        </div>

        {hasChildren && isExpanded && (
          <div className="ml-8 border-l-2 border-blue-200 pl-4 animate-fadeIn">
            {user.children.map((child) => renderUserNode(child, level + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50">
      {/* Header */}
      <div className="bg-white/80 backdrop-blur-lg border-b border-gray-200 sticky top-0 z-10">
        <div className="container mx-auto px-4 py-6">
          <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
            <div>
              <h1 className="text-3xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent flex items-center gap-3">
                <FiGitBranch className="text-blue-600" />
                Organigramme
              </h1>
              <p className="text-gray-600 mt-1">Structure hiérarchique de l'organisation</p>
            </div>
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="relative">
                <FiSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input
                  type="text"
                  placeholder="Rechercher..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                />
              </div>
              <button
                onClick={loadOrgChart}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2"
              >
                <FiRefreshCw className="w-4 h-4" />
                Actualiser
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-8">
        {/* Stats Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Total utilisateurs</p>
                <p className="text-2xl font-bold text-gray-900">{users.length}</p>
              </div>
              <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center">
                <FiUsers className="w-6 h-6 text-blue-600" />
              </div>
            </div>
          </div>
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Départements</p>
                <p className="text-2xl font-bold text-gray-900">{Object.keys(filteredDepartmentHierarchy).length}</p>
              </div>
              <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center">
                <FiBriefcase className="w-6 h-6 text-green-600" />
              </div>
            </div>
          </div>
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Admins</p>
                <p className="text-2xl font-bold text-gray-900">{users.filter(u => u.role === 'admin').length}</p>
              </div>
              <div className="w-12 h-12 bg-red-100 rounded-lg flex items-center justify-center">
                <FiShield className="w-6 h-6 text-red-600" />
              </div>
            </div>
          </div>
          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Validateurs</p>
                <p className="text-2xl font-bold text-gray-900">{users.filter(u => u.role === 'validator').length}</p>
              </div>
              <div className="w-12 h-12 bg-purple-100 rounded-lg flex items-center justify-center">
                <FiAward className="w-6 h-6 text-purple-600" />
              </div>
            </div>
          </div>
        </div>

        {/* Department Hierarchy */}
        <div className="space-y-6">
          {loading ? (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-12 text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
              <p className="text-gray-600">Chargement de l'organigramme...</p>
            </div>
          ) : filteredUsers.length === 0 ? (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-12 text-center">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                <FiUsers className="w-10 h-10 text-gray-400" />
              </div>
              <h3 className="text-lg font-semibold text-gray-900 mb-2">
                {searchTerm ? 'Aucun résultat trouvé' : 'Aucun utilisateur'}
              </h3>
              <p className="text-gray-600">
                {searchTerm ? 'Essayez de modifier votre recherche' : 'Aucun utilisateur actif dans le système'}
              </p>
            </div>
          ) : (
            Object.entries(filteredDepartmentHierarchy).map(([departmentKey, group]) => {
              const isExpanded = expandedDepartments[departmentKey];
              const userCount = group.users.length;

              return (
                <div key={departmentKey} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden animate-fadeIn">
                  <div className="bg-gradient-to-r from-blue-600 to-indigo-600 p-6">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white/20 rounded-lg flex items-center justify-center">
                          <FiBriefcase className="w-6 h-6 text-white" />
                        </div>
                        <div>
                          <h2 className="text-xl font-bold text-white">{group.label}</h2>
                          <p className="text-blue-100">{userCount} utilisateur(s)</p>
                        </div>
                      </div>
                      <button
                        onClick={() => toggleDepartment(departmentKey)}
                        className="p-2 text-white/80 hover:text-white hover:bg-white/20 rounded-lg transition-colors"
                      >
                        {isExpanded ? <FiChevronDown className="w-5 h-5" /> : <FiChevronRight className="w-5 h-5" />}
                      </button>
                    </div>
                  </div>

                  {isExpanded && (
                    <div className="p-6 space-y-4 animate-fadeIn">
                      {group.users.map((user) => renderUserNode(user))}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

export default OrgChart;
